CustomField.formula:
/* Web Customer Comments */
IF(AND(ISPICKVAL(Origin, "Web"),NOT(Read_All_Customer_Comments__c),OR(ISPICKVAL(Status, "New"),ISPICKVAL(Status,"Escalated"),ISPICKVAL(Status, "In Progress"))),IMAGE("/resource/web_icon", "New Web", 20, 20),
IF(AND(ISPICKVAL(Origin, "Web"),NOT(Read_All_Customer_Comments__c)),IMAGE("/img/samples/flag_red.gif","Unread Web Comment"),
/* Email Indicator for NON-WEB */
IF(AND(NOT(ISPICKVAL(Origin, "Web")),NOT(Read_All_Emails__c),OR(ISPICKVAL(Status, "New"),ISPICKVAL(Status, "Escalated"),ISPICKVAL(Status, "In Progress"))),IMAGE("/servlet/servlet.FileDownload?file=0152p000008ZxH8","New Email"),

IF(AND(NOT(ISPICKVAL(Origin, "Web")),NOT(Read_All_Emails__c)),IMAGE("/img/samples/flag_red.gif","Email Received"),"")) ))
